export function parseQuery(text: string): [string, string][] {
  if (!text) return [];
  return text.split('&').map((part) => {
    const [key, value] = part.split('=');
    if (!key || value === undefined) throw new Error('Invalid query');
    return [key, value];
  });
}
export function serializeQuery(ast: [string, string][]): string {
  return ast.map(([key, value]) => `${key}=${value}`).join('&');
}

