import { test } from 'node:test';
import assert from 'node:assert/strict';
import { parseQuery, serializeQuery } from '../src/parser/query.ts';
test('escaped filters round trip', () => {
  const values = ['', 'plain', 'a&b=c', '"quoted"', 'snowman ☃', '%20', 'back\\slash'];
  for (const value of values) {
    const ast = [['name', value], ['other', 'x=y&z']];
    assert.deepEqual(parseQuery(serializeQuery(ast)), ast);
  }
  assert.deepEqual(parseQuery('name=a%26b%3Dc'), [['name', 'a&b=c']]);
  assert.deepEqual(parseQuery(''), []);
});
test('malformed filters reject', () => {
  for (const input of ['missing', '=empty-key', 'name=%ZZ']) assert.throws(() => parseQuery(input));
});

