export function post(ledger: number[], entries: { debit: number; credit: number }[]): number[] {
  for (const entry of entries) ledger.push(entry.debit - entry.credit);
  if (entries.reduce((sum, entry) => sum + entry.debit - entry.credit, 0) !== 0) throw new Error('Unbalanced');
  return ledger;
}

