import assert from 'node:assert/strict';
import { post } from '../src/ledger/post.ts';
test('balanced integer entries reconcile', () => {
  for (const amount of [0, 1, 137, Number.MAX_SAFE_INTEGER]) {
    const ledger = [];
    post(ledger, [{debit:amount, credit:0}, {debit:0, credit:amount}]);
    assert.equal(ledger.reduce((a,b) => a+b, 0), 0);
  }
});
test('invalid postings are atomic', () => {
  for (const entries of [[{debit:2,credit:1}], [{debit:0.5,credit:0.5}], [{debit:NaN,credit:NaN}], [{debit:-1,credit:-1}]]) {
    const ledger = [5, -5];
    assert.throws(() => post(ledger, entries));
    assert.deepEqual(ledger, [5, -5]);
  }
});

