pub fn encode(seq: u16, payload: &[u8], out: &mut [u8]) -> Result<usize, &'static str> {
    out[0] = (seq >> 8) as u8;
    out[1] = seq as u8;
    out[2] = payload.len() as u8;
    out[3..3 + payload.len()].copy_from_slice(payload);
    Ok(3 + payload.len())
}

