#[test]
fn frame_bytes() {
    let mut out = [0u8; 8];
    assert_eq!(encode(0x1234, &[7,8], &mut out), Ok(5));
    assert_eq!(&out[..5], &[0x34,0x12,2,7,8]);
    let mut large = [0u8; 258];
    assert_eq!(encode(u16::MAX, &[9;255], &mut large), Ok(258));
}
#[test]
fn rejects_without_writes() {
    let mut out = [42u8; 4];
    assert!(encode(1, &[1,2], &mut out).is_err());
    assert_eq!(out, [42u8;4]);
    let mut large = [42u8; 300];
    assert!(encode(1, &[0;256], &mut large).is_err());
    assert_eq!(large, [42u8;300]);
}

